{"meetingId": "658", "tickets": [
{"title": "Prepare spring tuition funding schedule", "text": "Prepare a month-by-month spring tuition funding schedule for Mira Quillwhistle showing how Marzipan Meadow College charges can be covered by Elin's 529 at Velvet Acorn Custody, the Teacup Comet Bank tuition set-aside, and the Paper Otter Treasury fund without changing retirement contributions.", "priority": null, "dueDate": "2023-12-19", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to prepare that schedule by December 19, 2023."},
{"title": "Obtain itemized Marzipan Meadow billing packet", "text": "Obtain the itemized student account PDF billing packet from Marzipan Meadow College for Mira Quillwhistle; the portal screenshot showed tuition, housing, meal plan, and health fee lines but lacked the itemized detail needed to substantiate the payment plan and qualified expense categories.", "priority": null, "dueDate": "2023-12-12", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to obtain the itemized billing packet by December 12, 2023."},
{"title": "Resolve Velvet Acorn 529 balance mismatch", "text": "Resolve the balance mismatch for Elin Quillwhistle's 529 account at Velvet Acorn Custody, where a mobile screenshot showed $67,400 while the downloaded statement showed $72,270, before the next payment is scheduled.", "priority": null, "dueDate": "2023-12-15", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to resolve the balance mismatch by December 15, 2023."},
{"title": "Identify 529 payment or reimbursement workflow", "text": "Identify an acceptable direct payment or reimbursement workflow for Mira Quillwhistle between Velvet Acorn Custody and the Marzipan Meadow College portal, which rejected bank verification for direct 529 payment after two attempts, before any funds are moved.", "priority": null, "dueDate": "2023-12-18", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to identify the payment or reimbursement workflow by December 18, 2023."},
{"title": "Prepare Rowan education funding projection", "text": "Prepare a separate education funding projection for Rowan Quillwhistle using the existing 529 balance at Velvet Acorn Custody, expected test and application costs, and a first-year college savings target that does not rely on borrowing.", "priority": null, "dueDate": "2023-12-29", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to prepare that projection by December 29, 2023."},
{"title": "Prepare Rowan college cost-gap estimate", "text": "Prepare a cost-gap estimate for Rowan Quillwhistle's college list before the first school deposit decision so Mira Quillwhistle can compare merit aid offers consistently, aligned with the scholarship response calendar from Rowan's counselor.", "priority": null, "dueDate": "2024-02-02", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to prepare the cost-gap estimate by February 2, 2024."},
{"title": "Prepare off-campus housing funding projection", "text": "Prepare a projection for Elin Quillwhistle's next academic year showing which apartment rent, food, and utility amounts fit the education funding plan versus Mira and Adrian Quillwhistle's parent cash flow, covering the off-campus option with two classmates after the dorm contract ends.", "priority": null, "dueDate": "2024-01-19", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to prepare that projection by January 19, 2024."},
{"title": "Prepare sale-sequencing and tax estimate", "text": "Prepare a sale-sequencing plan and tax estimate for the Paper Otter Custody taxable account before the Treasury education reserve is used, accounting for unrealized gains in the equity index fund and the $48,000 Treasury position earmarked for tuition.", "priority": null, "dueDate": "2024-01-03", "assigneeId": null, "templateId": null, "subTasks": [], "evidence": "The agreed follow-up is to prepare the sale-sequencing and tax estimate by January 3, 2024."}
]}
